import * as T from './vendor/three.module.js';
import {makePerson,animatePerson} from './town-life/people/models.mjs';
import {population} from './town-life/people/core.mjs';
const views=new WeakMap();
export function attachSceneLife(group,plan,getState,heightAt=()=>0,scale=.1){const paths=(plan.paths||[]).filter(p=>p.points.length>1&&p.points.some((v,i)=>i&&Math.hypot(v.x-p.points[i-1].x,v.z-p.points[i-1].z)>1)),root=new T.Group();root.scale.setScalar(scale);group.add(root);const actors=[],people=population(plan.seed||41,'alder');for(let i=0;i<Math.min(5,paths.length);i++){const path=paths[i].points.map(p=>new T.Vector2(p.x,p.z)),person=structuredClone(people[i%people.length]),model=makePerson(person);model.userData.inertiaLayer='people';model.userData.walkedMetres=0;model.userData.routeVisits=0;model.traverse(o=>{o.userData.sharedGeometry=true;if(o.material)o.material.userData.shared=true;});root.add(model);actors.push({model,path,index:1,direction:1,position:path[0].clone()});}
 let elapsed=getState()?.seconds||0;function update(dt){const state=getState();if(!state)return;elapsed+=dt;state.seconds=Math.max(state.seconds,elapsed);for(const a of actors){let budget=dt*1.2,moved=0;while(budget>0){const target=a.path[a.index],v=target.clone().sub(a.position),len=v.length(),step=Math.min(len,budget);if(len>1e-6){a.position.addScaledVector(v,step/len);a.model.rotation.y=Math.atan2(v.x,v.y);}budget-=step;moved+=step;if(len<=step+.00001){a.index+=a.direction;if(a.index===a.path.length||a.index<0){a.direction*=-1;a.index+=a.direction*2;state.trips++;a.model.userData.routeVisits++;}}if(step===0&&budget>0)budget-=.001;}state.metres+=moved;a.model.userData.walkedMetres+=moved;animatePerson(a.model,{text:'Walking the local paths'},moved,dt,false);a.model.position.set(a.position.x,heightAt(plan.center.x+a.position.x,plan.center.z+a.position.y)+.04+a.model.position.y,a.position.y);}}
 update(0);views.set(group,{update});return root;}
export function animateSceneLife(group,dt){views.get(group)?.update(dt);}
